/* --- 醉江南 v1.3 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影./

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond&display=swap'); /* 英文 */
@import url("https://fontsapi.zeoseven.com/467/main/result.css"); /* 奈落旧宋体 - 全局 */
@import url("https://fontsapi.zeoseven.com/796/main/result.css"); /* Hangeuljaemin4.0 - 代码 */
@import url("https://fontsapi.zeoseven.com/445/main/result.css"); /* 云峰静龙行书 - 引用/斜体 */
@import url("https://fontsapi.zeoseven.com/446/main/result.css"); /* 云峰飞鱼体 - 标题 */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --color-bg-main: #f2f8ff;
    --color-primary-light: #E3f2ff;
    --color-primary-medium: #Beddff;
    --color-primary-accent: #9bcaff;
    --color-text-main: #335A88;
    --color-text-subtle: #6B8EAE;
    --color-accent-soft: #E6A5B5; /* 点缀色 */

    --theme-bg: var(--color-bg-main);
    --panel-bg-color: rgba(227, 242, 255, 0.85); /* 导航栏/抽屉背景 */
    --panel-bg-hover: rgba(190, 221, 255, 0.95);
    --card-bg: rgba(227, 242, 255, 0.9);
    --input-bg: rgba(227, 242, 255, 0.9); /* 输入框背景 */
    --text-main: var(--color-text-main);
    --text-subtle: var(--color-text-subtle);
    --border-color: rgba(155, 202, 255, 0.4);
    --accent-color: var(--color-primary-accent);
    --selected-color: var(--color-accent-soft);

    --font-english: "Cormorant Garamond", serif;
    --font-main: "NanoOldSong-A", var(--font-english);
    --font-quote: "YFJLXS", var(--font-english);
    --font-code: "Hangeuljaemin4.0", monospace;
    --font-title: "YFFYT", var(--font-english);

    --border-radius: 12px;
}

/* --- 3. 全局样式 --- */
body { background-color: var(--theme-bg) !important; color: var(--text-main); font-family: var(--font-main); }
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; box-shadow: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); }

/* --- 4. 顶部导航栏 --- */
#top-settings-holder {
    background-color: var(--panel-bg-color);
    box-shadow: none;
    border: none;
    backdrop-filter: blur(8px);
    background-image: none;
    position: relative;
    margin-bottom: 20px;
}

/* 挂饰 (右侧) */
#top-settings-holder::before {
    content: '';
    display: block;
    width: 200px;
    height: 200px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/2vR1/2048X2048/2026-02-25_164303.png/webp');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: top right;
    position: absolute;
    top: -20px;
    right: -30px;
    opacity: 1;
    z-index: 10;
    pointer-events: none;
}

/* 导航栏底部装饰分割线 */
#top-settings-holder::after {
    content: '';
    position: absolute;
    bottom: -40px;
    left: 0;
    width: 100%;
    height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/XFVS/2048X2048/2026-02-25_171418.png/webp');
    background-size: auto 100%;
    background-repeat: repeat-x;
    z-index: 11;
    pointer-events: none;
}

.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; }
.drawer-icon.fa-fw:hover { transform: scale(1.1); }

#ai-config-button .drawer-icon, .drawer-icon.fa-sliders { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }
#sys-settings-button .drawer-icon, .drawer-icon.fa-plug { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/QDWg/2048X2048/2026-02-25_162900.png/webp'); }
#advanced-formatting-button .drawer-icon, .drawer-icon.fa-font { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }
#WI-SP-button .drawer-icon, .drawer-icon.fa-book-atlas { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/QDWg/2048X2048/2026-02-25_162900.png/webp'); }
#user-settings-button .drawer-icon, .drawer-icon.fa-user { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }
#backgrounds-button .drawer-icon, .drawer-icon.fa-image { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/QDWg/2048X2048/2026-02-25_162900.png/webp'); }
#extensions-settings-button .drawer-icon, .drawer-icon.fa-cubes { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }
#persona-management-button .drawer-icon, .drawer-icon.fa-face-smile { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }
#character_popup_button .drawer-icon, .drawer-icon.fa-address-card { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/QDWg/2048X2048/2026-02-25_162900.png/webp'); }
#table_database_settings_drawer .drawer-icon, .drawer-icon.fa-bars-progress { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/QDWg/2048X2048/2026-02-25_162900.png/webp'); }
.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/xkDd/4095X2493/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D760310562676547395%26skey%3D%40crypt_5a237c93_16e7d1aec608410794da4f9660273775%26mmweb_appid%3Dwx_webfilehelper.jpg/webp'); background-size: cover; background-position: center; border: none; border-radius: var(--border-radius); box-shadow: none; }

/* --- 5. 底部输入栏 --- */
#send_textarea { clip-path: none !important; background-color: transparent !important; border: none !important; }
#send_form { 
    border-radius: 25px;
    background-image: none !important;
    background-color: var(--input-bg) !important;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: none !important;
    position: relative;
    transition: all 0.5s ease;
    padding: 10px 15px;
}
#send_form:hover { 
    transform: translateY(-5px);
    background-color: var(--panel-bg-hover) !important;
}
#rightSendForm, #leftSendForm { gap: 5px; }
#send_form:has(#send_textarea:focus-visible) { outline: none; }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/zQ3d/2048X2048/2026-02-25_163348.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/T2VD/2048X2048/2026-02-25_163408.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/BiFa/2048X2048/2026-02-25_163431.png/webp'); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/N3Yx/2048X2048/2026-02-25_162824.png/webp'); }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "落笔生花，言语如画...";
    color: var(--text-subtle);
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--font-main);
    font-size: 0.5em;
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
    opacity: 0.8;
}

/* --- 6. 核心：消息布局与样式 --- */
/* 增加底部间距(margin-bottom)以容纳下沉的装饰物，防止遮挡下一条消息 */
.mes { display: flex; flex-direction: column; align-items: stretch; gap: 0; padding: 0 !important; margin: 40px auto 140px auto !important; width: 90%; max-width: 700px; background: transparent !important; border: none !important; box-shadow: none !important; overflow: visible !important; position: relative; }

.mes .mesAvatarWrapper {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0px 20px;
    align-items: center;
    padding: 20px 30px;
    border-radius: 0;
    width: 100%;
    max-width: none;
    background-size: cover;
    background-position: center;
    position: relative;
    z-index: 5;
    min-height: 160px;
    overflow: visible !important;
}

.mes[is_user="true"] .mesAvatarWrapper { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/Qzol/4578X2298/2026-02-25_180833.png/webp');
    grid-template-columns: 1fr 100px;
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/h5Io/4578X2298/2026-02-25_180824.png/webp'); }

.mes .mesAvatarWrapper > * { position: relative; z-index: 25; }

.mes .avatar { grid-row: 1 / 3; grid-column: 1 / 2; width: 85px !important; height: 85px !important; flex-shrink: 0; display: block !important; position: relative; transform: rotate(-4deg); transition: transform 0.4s ease; }

.mes[is_user="true"] .avatar { grid-column: 2 / 3; }
.mes .avatar:hover { transform: rotate(0deg); }
.mes .avatar img { 
    border-radius: 0 !important;
    border: none !important; 
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* 恢复头像白色外框 */
.mes .avatar::before {
    content: '';
    position: absolute;
    top: -4px; left: -4px; right: -4px; bottom: -4px;
    border: 3px solid rgba(255, 255, 255, 0.8);
}

/* AI头像左侧装饰 (放大) */
.mes[is_user="false"] .avatar::after {
    content: '';
    position: absolute;
    bottom: -25px; left: -45px;
    width: 150px; height: 150px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/SrY0/2048X2048/2026-02-25_163601.png/webp');
    background-size: contain;
    background-repeat: no-repeat;
    z-index: -1;
    pointer-events: none;
}

/* 用户头像右侧装饰 (放大) */
.mes[is_user="true"] .avatar::after {
    content: '';
    position: absolute;
    bottom: -25px; right: -45px;
    width: 150px; height: 150px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/AO6X/2048X2048/2026-02-25_165558.png/webp');
    background-size: contain;
    background-repeat: no-repeat;
    z-index: -1;
    pointer-events: none;
}

.mes .mesAvatarWrapper > .ch_name { grid-row: 1 / 2; grid-column: 2 / 3; display: block !important; font-weight: bold; font-size: 1.2em; color: var(--text-main); margin-bottom: 5px; font-family: var(--font-title); text-shadow: 0 1px 3px rgba(255,255,255,0.5); }
.mes .mesAvatarWrapper > .mes_timer, .mes .mesAvatarWrapper > .mesIDDisplay, .mes .mesAvatarWrapper > .tokenCounterDisplay { display: none !important; }
.mes[is_user="true"] .mesAvatarWrapper > .ch_name { grid-column: 1 / 2; text-align: right; }

/* 底部padding调整，为下方外挂的装饰物留出视觉连接点 */
.mes .mes_block { 
    background-color: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(5px);
    border: none;
    border-radius: 0;
    padding: 25px 30px 60px 30px;
    margin-top: 0;
    position: relative;
    overflow: visible !important;
}

.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

/* 提升文字层级，确保在任何情况下文字都在装饰物之上 */
.mes .mes_text { line-height: 1.9; color: var(--text-main); position: relative; z-index: 30; }

#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; box-shadow: none !important; border-radius: 0; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; color: var(--text-subtle) !important; font-size: 0.9em !important; display: inline-flex !important; align-items: center !important; transition: none !important; }
.mes_reasoning_arrow { display: none !important; }

.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "烟雨江南，思绪如帘"; font-family: var(--font-title); font-size: 14px !important; color: var(--text-main); visibility: visible; }

.mes_reasoning { border-left: 3px solid var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; }

/* --- 7. 文本样式 --- */
.mes_text strong, .mes_text b { font-family: var(--font-title); color: var(--color-accent-soft); font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--accent-color); position: relative; padding: 0 0.5em; }
.mes_text em::before, .mes_text i::before { content: '「'; position: absolute; left: 0; top: 0; }
.mes_text em::after, .mes_text i::after { content: '」'; position: absolute; right: 0; top: 0; }
.mes_text blockquote { background-color: rgba(155, 202, 255, 0.2); border-left: 4px solid var(--accent-color); padding: 10px 15px; border-radius: 0 8px 8px 0; margin: 10px 0; }
.mes_text code { font-family: var(--font-code); background-color: rgba(155, 202, 255, 0.25) !important; color: var(--text-main) !important; padding: 2px 6px; border-radius: 6px; border: none; }

.mes .mes_block > *:not(.mes_buttons) { position: relative; z-index: 30; }

/* --- 消息框底部装饰 (画框式布局，彻底移出文字区) --- */
/* 用户消息框 (桥) - 右下方外挂 */
.mes[is_user="true"] .mes_block::after {
    content: ''; display: block; position: absolute;
    bottom: -60px; 
    right: -80px;   /* 向右移出 */
    width: 220px; height: 220px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/SowI/2048X2048/2026-02-25_155209.png/webp');
    background-size: contain; background-repeat: no-repeat;
    pointer-events: none; 
    z-index: 0; /* 层级低于文字 */
    opacity: 0.9;
}

/* AI消息框 (花) - 左下方外挂 */
.mes[is_user="false"] .mes_block::after {
    content: ''; display: block; position: absolute;
    bottom: -70px; /* 大幅下移 */
    left: -45px;    /* 向左移出 */
    width: 90px; height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/khdg/2300X1906/2026-02-25_201903.png/webp');
    background-size: contain; background-repeat: no-repeat;
    pointer-events: none; 
    z-index: 0; /* 层级低于文字 */
    opacity: 0.9;
}


/* --- 8. 元素重定位与自定义文本 --- */
.mes_block > .ch_name {
    position: absolute !important;
    top: -35px !important;
    left: 10px;
    right: 10px;
    height: 30px;
    display: flex !important;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    z-index: 100 !important;
    pointer-events: auto !important;
    background: transparent !important;
}

.mes[is_user="true"] .mes_block > .ch_name {
    flex-direction: row-reverse;
    justify-content: flex-end;
}

.mes_block .ch_name .name_text,
.mes_block .ch_name .timestamp {
    display: inline-block !important;
    font-size: 12px;
    color: var(--text-subtle);
    text-shadow: 0 1px 2px rgba(255,255,255,0.8);
    white-space: nowrap;
}

.mes_block .mes_buttons {
    display: flex !important;
    align-items: center;
    gap: 5px;
    opacity: 0.8;
    transition: all 0.2s ease;
}

.mes_block .mes_buttons:hover {
    opacity: 1;
    transform: scale(1.05);
}

/* 楼层计数器 */
#chat { counter-reset: ID-counter 0; }
.mes { counter-increment: ID-counter; }

.mes::after {
    content: '江南一梦 · 第 ' counter(ID-counter) ' 卷 · 扁舟一叶';
    display: block;
    text-align: center;
    margin: 50px auto 0; /* 调整间距 */
    padding: 5px 15px;
    background-color: var(--card-bg);
    border: none;
    border-radius: 0;
    font-size: 12px;
    color: var(--text-subtle);
    font-family: var(--font-main);
    max-width: 80%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* --- 9. 全局UI颜色与样式统一 --- */
* { box-shadow: none !important; border-color: var(--border-color) !important;}
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, .range-block-title.justifyLeft.standoutHeader, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 {
    background-image: none !important; background: var(--card-bg) !important; border: none !important; border-radius: var(--border-radius) !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole {
    background-color: var(--input-bg) !important; border: 1px solid transparent !important; color: var(--text-main) !important; border-radius: 8px !important; }
input:focus, textarea:focus, select:focus { background-color: var(--panel-bg-hover) !important; border-color: var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; color: var(--text-main) !important; transition: all 0.2s ease; border: none !important; }
.menu_button:hover { background-color: var(--accent-color) !important; color: white !important; }
input[type="checkbox"] { filter: none !important; border: none !important; background-color: rgba(155, 202, 255, 0.2); }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }
.prompt_order > div { background-color: var(--card-bg) !important; border: none !important; }

