dialog.popup { position: relative; overflow: hidden; background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260225/xkDd/4095X2493/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D760310562676547395%26skey%3D%40crypt_5a237c93_16e7d1aec608410794da4f9660273775%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important;
    background-size: cover !important;
    background-position: center !important;
    border: none !important;
    border-radius: var(--border-radius) !important;
    position: relative;
}
dialog.popup::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-color: transparent !important;
    border-radius: var(--border-radius);
    z-index: 0;
}
dialog.popup .popup-body, #dialogue_popup { background-color: transparent !important; z-index: 1; }

.menu_button.active, .menu_button.world_set, .menu_button.fav_on { background-color: var(--selected-color) !important; color: white !important; font-weight: bold; }
.menu_button.active:hover, .menu_button.world_set:hover, .menu_button.fav_on:hover { filter: brightness(1.05); }

#left-nav-panel, #left-nav-panel * { color: var(--text-main) !important; text-shadow: none !important; }
#left-nav-panel .standoutHeader, #left-nav-panel .menu_button, #left-nav-panel select { background-color: var(--card-bg) !important; color: var(--text-main) !important; border: none !important; }
#left-nav-panel .menu_button:hover { background-color: var(--accent-color) !important; color: white !important; }
#left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: white !important; }

.select2-container--default .select2-selection--multiple .select2-selection__choice { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; }
.select2-container--default .select2-selection--multiple .select2-selection__choice__remove { color: var(--text-subtle) !important; transition: color 0.2s ease; }
.select2-container--default .select2-selection--multiple .select2-selection__choice__remove:hover { color: var(--text-main) !important; }
