/* --- 10. Markdown文本样式重定义 --- */

.mes_text h1, .mes_text h2 {
    font-family: var(--font-title) !important;
    font-weight: normal !important;
    color: var(--color-text-main) !important; /* 主文本蓝色 */
    border-bottom: 2px dashed rgba(155, 202, 255, 0.6); /* 柔和的虚线底边 */
    padding-bottom: 6px; /* 增加与下划线的距离 */
    margin: 1.5em 0 1em 0 !important; /* 调整上下间距 */
    letter-spacing: 1px; /* 略微收敛字间距，更内敛 */
    text-shadow: none;
}
.mes_text strong, .mes_text b {
    font-family: var(--font-title) !important; /* 榜书字体强调 */
    font-weight: normal !important;
    color: var(--color-accent-soft) !important; /* 柔和点缀色，醒目但不刺眼 */
    padding: 0 4px; /* 增加左右内边距，使其更突出 */
    background-color: rgba(255, 255, 255, 0.2); /* 极淡的背景，模拟宣纸留白 */
    border-radius: 4px;
    text-shadow: 0 1px 2px rgba(0,0,0,0.1); /* 极其轻微的阴影，提升立体感 */
}
.mes_text em, .mes_text i {
    font-family: var(--font-quote) !important; /* 行书字体，优雅飘逸 */
    font-style: normal !important;
    color: var(--color-primary-accent) !important; /* 明亮的蓝色强调 */
    margin: 0 4px; /* 调整间距 */
    opacity: 0.95; /* 略微透明，更显轻盈 */
    text-shadow: 0 0 1px rgba(255,255,255,0.3); /* 轻微光泽感 */
}
/* 引用/引号包裹的文字，保持原有的「」样式，但调整引号颜色 */
.mes_text em::before, .mes_text i::before,
.mes_text em::after, .mes_text i::after {
    color: var(--color-text-subtle); /* 引号颜色与次要文字保持一致 */
    font-size: 0.9em; /* 引号略小 */
    opacity: 0.8;
}

/* --- 单独修改：被引号包裹的文字效果 (对话/引用) --- */
.mes_text q, 
.mes_text .quote {
    font-family: var(--font-quote) !important; 
    font-style: normal !important;
    font-weight: normal !important;
    /* 颜色：使用稍深一点的黛蓝色，模拟湿墨在宣纸上晕开的效果 */
    color: #4A6E91 !important; 

    background: rgba(190, 221, 255, 0.2) !important; 
    padding: 2px 6px !important;
    margin: 0 2px !important;
    border-radius: 4px;

    text-shadow: 0 0 1px rgba(155, 202, 255, 0.5); 
    display: inline;
    border: none !important; /* 确保没有边框干扰 */
}


/* 如果引号内有加粗，微调加粗颜色以防冲突 */
.mes_text q strong, 
.mes_text q b {
    color: var(--color-accent-soft) !important; /* 对话中的强调使用点缀粉 */
    background: transparent !important;
    text-shadow: none !important;
}
